#!/bin/sh
set -eu
umask 077
exec python3 - <<'PY'
import base64,hashlib,json
MODULE_SHA256 = '2cf05676933aaa2ee2d6f67eef86f2cfb8e322279947423485263a4da7acccd9'
MODULE_B64 = ''
EXPECTED_PARENT_CHAIN = None  # PIN_FROM_AUTHORIZED_READ_ONLY_SERVER_SNAPSHOT
OPERATION_NONCE = '9ea1a70f1fe043c6b5ee03eebd42aff6'
source = base64.b64decode(MODULE_B64, validate=True)
if hashlib.sha256(source).hexdigest() != MODULE_SHA256:
    raise RuntimeError('EMBEDDED_MODULE_HASH_MISMATCH')
if (not isinstance(EXPECTED_PARENT_CHAIN, list) or len(EXPECTED_PARENT_CHAIN) != 3 or
    any(not isinstance(row, list) or len(row) != 4 or
        any(type(v) is not int or v < 0 for v in row) or row[2] != 0 or
        row[3] > 0o7777 or row[3] & 0o022 for row in EXPECTED_PARENT_CHAIN)):
    raise RuntimeError('REAL_PARENT_SNAPSHOT_NOT_PINNED')
module = {'__name__': 'reviewed_bootstrap_fence',
          'VERIFIED_MODULE_SHA256': MODULE_SHA256}
exec(compile(source, '<pinned-fence-module>', 'exec'), module)
# REVIEWED_MODULE_READY
result = module['create_fence'](EXPECTED_PARENT_CHAIN, OPERATION_NONCE)
print(json.dumps(result, sort_keys=True, separators=(',', ':')), flush=True)
PY
